SELECT location, dept_name, COUNT_IF(dept_name = 'Sales') AS sales_events, SUM(budget) FILTER (WHERE location = 'Tokyo') AS tokyo_total_budget, COUNT_IF(location = 'Singapore') AS singapore_events, ROUND(SUM(budget) / NULLIF(COUNT(CASE WHEN location = 'Bangkok' THEN 1 END), 0), 2) AS budget_per_bangkok FROM departments GROUP BY location, dept_name HAVING COUNT_IF(dept_name = 'Sales') >= 1 ORDER BY singapore_events NULLS LAST;
